class Solution {
public:
    string decodeCiphertext(string encodedText, int rows) {
        int n = encodedText.size();
        if (n == 0) return "";
        int cols = n / rows;
        string result;
        result.reserve(n);
        for (int j = 0; j < cols; j++) {
            for (int i = 0; i < rows && j + i < cols; i++) {
                result.push_back(encodedText[i * cols + j + i]);
            }
        }
        while (!result.empty() && result.back() == ' ') {
            result.pop_back();
        }
        return result;
    }
};
